command_result.command:
mkdir -p /tmp/t1/accs && cd /tmp/t1 && cat > book.json <<'EOF'
{"currencies":{"EUR":{"cash":"none"},"SEK":{"cash":"whole"},"CHF":{"cash":"0.05"}},"tariffs":{"x":{"currency":"EUR","vat":"0.125","standing":"0","bands":[{"upto":null,"price":"0.125"}]},"s":{"currency":"SEK","vat":"0","standing":"0","bands":[{"upto":null,"price":"0.5"}]}}}
EOF
cat > accs/a.json <<'EOF'
{"account":"A","tariff":"x","period":{"start":"2026-03-01","end":"2026-03-01"},"readings":[{"kwh":"1"}]}
EOF
cat > accs/b.json <<'EOF'
{"account":"B","tariff":"s","period":{"start":"2026-03-01","end":"2026-03-01"},"readings":[{"kwh":"5"}],"credits":[{"ref":"c","amount":-0.1}]}
EOF
for r in /tmp/orig /app; do echo == $r; cd $r; python -m meterbill --tariffs /tmp/t1/book.json bill /tmp/t1/accs/a.json --format csv | tail -1; python -m meterbill --tariffs /tmp/t1/book.json batch /tmp/t1/accs --format csv | tail -2;  python -m meterbill --tariffs /tmp/t1/book.json batch /tmp/t1/accs| tail -5; python -m meterbill --tariffs /tmp/t1/book.json bill /tmp/t1/accs/b.json | grep -i 'payable\|Total'; done
